// ==========================
// 🔹 1. OBTENER RESPUESTA OPENAI
// ==========================
let raw = $input.first().json['0'].content[0].text;

raw = raw
  .replace(/```json/g, '')
  .replace(/```/g, '')
  .trim();

// ==========================
// 🔹 2. PARSEAR JSON
// ==========================
let parsed;

try {
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = {};
}

// ==========================
// 🔹 3. FUNCIONES UTILES
// ==========================
const normalize = (str) =>
  str?.toLowerCase()
     ?.normalize("NFD")
     .replace(/[\u0300-\u036f]/g, "")
     .trim() || null;

const unique = (arr) => [...new Set(arr)];
const toNumber = (value) => {
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
};

const cleanReceiptNumber = (value) =>
  value ? String(value).replace(/\s/g, '') : null;

const splitWords = (str) =>
  normalize(str)?.split(/\s+/).filter(Boolean) || [];
const cleanPersonName = (value) => {
  let s = normalize(value);
  if (!s) return null;

  s = s
    .replace(/^(de|del|desde|emisor|remitente|ordenante|origen)\s+/i, "")
    .replace(/^(a|para|beneficiario|titular|destinatario|destino|receptor)\s+/i, "")
    .replace(/\s+/g, " ")
    .trim();

  return s || null;
};

const bestNameMatch = (candidates, expected) => {
  const cleanExpected = normalize(expected);
  const cleanCandidates = unique(candidates.map(cleanPersonName).filter(Boolean));

  if (!cleanExpected || !cleanCandidates.length) {
    return {
      name: null,
      ratio: 0,
    };
  }

  let best = {
    name: null,
    ratio: 0,
  };

  for (const candidate of cleanCandidates) {
    const ratio = Math.max(
      wordMatchRatio(candidate, cleanExpected),
      wordMatchRatio(cleanExpected, candidate)
    );

    if (ratio > best.ratio) {
      best = {
        name: candidate,
        ratio,
      };
    }
  }

  return best;
};

const safeArray = (value) => Array.isArray(value) ? value : [];

const toDateOnly = (value) => {
  if (!value) return null;
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return null;
  return new Date(date.getFullYear(), date.getMonth(), date.getDate());
};

const isWeekend = (date) => {
  if (!date) return false;
  const day = date.getDay();
  return day === 0 || day === 6;
};

const wordMatchRatio = (sourceA, sourceB) => {
  const wordsA = unique(splitWords(sourceA));
  const wordsB = unique(splitWords(sourceB));

  if (!wordsA.length || !wordsB.length) {
    return 0;
  }

  let matches = 0;

  for (const wordB of wordsB) {
    for (const wordA of wordsA) {
      if (wordA === wordB) {
        matches++;
        break;
      }

      if (wordA.length >= 4 && wordB.length >= 4) {
        if (
          wordA.includes(wordB.slice(0, 4)) ||
          wordB.includes(wordA.slice(0, 4))
        ) {
          matches++;
          break;
        }
      }
    }
  }

  return matches / wordsB.length;
};

// ==========================
// 🔹 4. DATOS DEL WEBHOOK
// ==========================
const webhook = $('Verificador').first().json.body;

const comprobanteWebhook = cleanReceiptNumber(webhook.numcomprobante);
const montoWebhook = toNumber(
  webhook.verification_hints?.expected_total_amount ?? webhook.valor
);
const titularWebhook = normalize(webhook.banco?.propietarioban);
const fechaWebhook = webhook.created_at;

const bancoAliasesWebhook = unique(
  safeArray(
    webhook.banco_aliases || webhook.verification_hints?.bank_match_terms || []
  )
    .map(normalize)
    .filter(Boolean)
);

const allowMultipleReceiptsTotalMatch =
  webhook.verification_hints?.allow_multiple_receipts_total_match !== false;

// ==========================
// 🔹 5. NORMALIZAR SALIDA OCR
// ==========================
// Soporta formato nuevo:
// - total_comprobantes
// - monto_total_detectado
// - banco_principal
// - comprobantes[]
//
// Y también formato viejo:
// - comprobante
// - monto
// - banco
// - fecha
// - titular

let comprobantes = safeArray(parsed.comprobantes);

if (!comprobantes.length) {
  comprobantes = [
    {
      comprobante: parsed.comprobante ?? null,
      monto: parsed.monto ?? null,
      banco: parsed.banco ?? parsed.banco_principal ?? null,
      fecha: parsed.fecha ?? null,
      titular: parsed.titular ?? null,
      emisor: parsed.emisor ?? null,
    }
  ];
}

comprobantes = comprobantes.map((item) => ({
  comprobante: cleanReceiptNumber(item?.comprobante),
  monto: toNumber(item?.monto),
  banco: normalize(item?.banco),
  fecha: item?.fecha || null,
  titular: cleanPersonName(item?.titular),
  emisor: cleanPersonName(item?.emisor),
}));

const totalComprobantes = toNumber(parsed.total_comprobantes) ?? comprobantes.length;

const bancoPrincipalOCR = normalize(parsed.banco_principal ?? parsed.banco);
const montoTotalDetectado =
  toNumber(parsed.monto_total_detectado) ??
  comprobantes.reduce((sum, item) => sum + (item.monto ?? 0), 0);

const fechasDetectadas = unique(
  [
    ...safeArray(parsed.fechas_detectadas),
    ...comprobantes.map((item) => item.fecha).filter(Boolean),
    parsed.fecha || null,
  ].filter(Boolean)
);

const bancosDetectados = unique(
  [
    bancoPrincipalOCR,
    ...comprobantes.map((item) => item.banco),
  ].filter(Boolean)
);

const comprobantesDetectados = unique(
  comprobantes.map((item) => item.comprobante).filter(Boolean)
);

const titularesDetectados = unique(
  comprobantes.map((item) => item.titular).filter(Boolean)
);

const emisoresDetectados = unique(
  comprobantes.map((item) => item.emisor).filter(Boolean)
);

const personasDetectadas = unique([
  ...titularesDetectados,
  ...emisoresDetectados,
  cleanPersonName(parsed.titular),
  cleanPersonName(parsed.emisor),
].filter(Boolean));

const mejorTitularOCR = titularesDetectados[0] || personasDetectadas[0] || cleanPersonName(parsed.titular);

// ==========================
// 🔹 6. VALIDACIONES
// ==========================
let aprobado = true;
let errores = [];
let advertencias = [];

// ✔ comprobante
if (comprobanteWebhook) {
  if (!comprobantesDetectados.length) {
    aprobado = false;
    errores.push("Comprobante no detectado");
  } else if (!comprobantesDetectados.includes(comprobanteWebhook)) {
    aprobado = false;
    errores.push("Comprobante no coincide");
  }
}

// ✔ comprobante sospechoso
for (const numero of comprobantesDetectados) {
  if (numero && /^(\d)\1+$/.test(numero)) {
    aprobado = false;
    errores.push("Comprobante sospechoso");
    break;
  }
}

// ✔ monto total
if (montoWebhook === null) {
  aprobado = false;
  errores.push("Monto webhook inválido");
} else {
  const montoComparar = allowMultipleReceiptsTotalMatch
    ? montoTotalDetectado
    : (comprobantes[0]?.monto ?? null);

  if (montoComparar === null || Math.abs(montoComparar - montoWebhook) > 0.01) {
    aprobado = false;
    errores.push("Monto total no coincide");
  }
}

// ✔ banco por alias
const bankMatches =
  bancosDetectados.length > 0 &&
  bancoAliasesWebhook.length > 0 &&
  bancosDetectados.some((bancoDetectado) =>
    bancoAliasesWebhook.some((alias) =>
      bancoDetectado === alias ||
      bancoDetectado.includes(alias) ||
      alias.includes(bancoDetectado)
    )
  );

if (!bankMatches) {
  aprobado = false;
  errores.push("Banco no coincide");
}

// ✔ titular
// ✔ titular / beneficiario
// No confiar ciegamente en el campo "titular" de la IA.
// Si la IA invirtió titular/emisor, buscamos cuál persona coincide mejor con el titular esperado del webhook.
let titularDetectadoFinal = mejorTitularOCR;
let titularRatioFinal = 0;
let titularCorregidoDesde = null;

if (titularWebhook) {
  const bestTitular = bestNameMatch(titularesDetectados, titularWebhook);
  const bestEmisor = bestNameMatch(emisoresDetectados, titularWebhook);
  const bestPersona = bestNameMatch(personasDetectadas, titularWebhook);

  titularDetectadoFinal = bestPersona.name || mejorTitularOCR;
  titularRatioFinal = bestPersona.ratio || 0;

  if (bestEmisor.ratio > bestTitular.ratio && bestEmisor.ratio >= 0.6) {
    titularCorregidoDesde = "emisor";
    advertencias.push("Titular corregido: la IA puso el beneficiario en emisor");
  }

  if (titularRatioFinal < 0.6) {
    aprobado = false;
    errores.push(`Titular no coincide (${Math.round(titularRatioFinal * 100)}%)`);
  }
}

// ✔ fecha
if (fechasDetectadas.length > 0) {
  const fechaWebhookDate = toDateOnly(fechaWebhook);

  if (!fechaWebhookDate) {
    aprobado = false;
    errores.push("Fecha webhook inválida");
  } else {
    const diffs = fechasDetectadas
      .map((fecha) => toDateOnly(fecha))
      .filter(Boolean)
      .map((fechaOcrDate) =>
        Math.abs((fechaWebhookDate - fechaOcrDate) / (1000 * 60 * 60 * 24))
      );

    if (!diffs.length) {
      aprobado = false;
      errores.push("Fecha no detectada");
    } else {
      const minDiffDias = Math.min(...diffs);

      let maxDias = 1;
      if (
        isWeekend(fechaWebhookDate) ||
        fechasDetectadas.some((fecha) => isWeekend(toDateOnly(fecha)))
      ) {
        maxDias = 3;
      }

      maxDias = Math.max(maxDias, 2);

      if (minDiffDias > maxDias) {
        aprobado = false;
        errores.push(`Fecha fuera de rango (${minDiffDias} días)`);
      }
    }
  }
} else {
  aprobado = false;
  errores.push("Fecha no detectada");
}

// ==========================
// 🚨 7. ANTIFRAUDE (IA)
// ==========================
if (parsed.legible === false) {
  aprobado = false;
  errores.push("Imagen no legible");
}

if (parsed.borroso === true) {
  aprobado = false;
  errores.push("Imagen borrosa");
}

if (parsed.editado === true) {
  aprobado = false;
  errores.push("Posible edición");
}

if (parsed.realista === false) {
  aprobado = false;
  errores.push("No parece real");
}

if (parsed.confianza !== undefined && parsed.confianza < 70) {
  aprobado = false;
  errores.push("Baja confianza IA");
}

// ==========================
// 🧠 8. SCORE ANTIFRAUDE
// ==========================
let score = 100;

if (parsed.borroso) score -= 20;
if (parsed.editado) score -= 40;
if (parsed.realista === false) score -= 40;
if (parsed.legible === false) score -= 30;

if (score < 60) {
  aprobado = false;
  errores.push("Score antifraude bajo");
}

// evitar errores duplicados
errores = unique(errores);

// ==========================
// 🧾 9. RESULTADO FINAL
// ==========================
return [
  {
    json: {
      aprobado,
      errores: errores.join(", "),
      advertencias: advertencias.join(", "),
      score,

      data_extraida: {
        total_comprobantes: totalComprobantes,
        comprobantes: comprobantesDetectados,
        monto_total_detectado: montoTotalDetectado,
        bancos_detectados: bancosDetectados,
        fechas_detectadas: fechasDetectadas,
        titulares_detectados: titularesDetectados,
        emisores_detectados: emisoresDetectados,
        personas_detectadas: personasDetectadas,

        titular_detectado_final: titularDetectadoFinal,
        titularWebhook: titularWebhook,
        titular_ratio_final: Math.round(titularRatioFinal * 100),
        titular_corregido_desde: titularCorregidoDesde,

        banco_aliases_webhook: bancoAliasesWebhook,
      },

      idrec: webhook.idrec,
      raw,
    }
  }
];

