let raw = $json.output ?? $json.text ?? '';
let data = null;

const toText = (v) => {
  if (v === undefined || v === null) return '';
  if (typeof v === 'string') return v;
  try { return JSON.stringify(v); } catch { return String(v); }
};

raw = toText(raw)
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .trim();

// 1) intento parse directo
try { data = JSON.parse(raw); } catch (_) {}

// 2) extraer bloque JSON dentro de texto mixto
if (!data) {
  const first = raw.indexOf('{');
  const last  = raw.lastIndexOf('}');
  if (first >= 0 && last > first) {
    try { data = JSON.parse(raw.slice(first, last + 1)); } catch (_) {}
  }
}

// 3) fallback: texto plano sin JSON — tomar solo el último párrafo
// para evitar enviar razonamiento interno al cliente
if (!data || typeof data !== 'object') {
  let replyText = raw;
  const parts = raw.split(/\n\n+/);
  if (parts.length > 1) {
    const lastMeaningful = parts.filter(p => p.trim().length > 0).pop();
    if (lastMeaningful && lastMeaningful.trim().length > 10) {
      replyText = lastMeaningful.trim();
    }
  }
  data = {
    subagente_codigo: null,
    reply_text: replyText || 'Gracias por tu mensaje. Enseguida te ayudo.',
    accion_tipo: 'ninguna',
    accion_requerida: false,
    accion_payload: null,
    escalar_humano: false,
    motivo_humano: null,
    confianza: 0
  };
}

// Sanitizar reply_text
let texto = toText(data.reply_text).replace(/\\n/g, '\n').trim();
